/* * @lc app=leetcode id=2929 lang=kotlin * * [2929] Distribute Candies Among Children II */ class Solution { fun distributeCandies(n: Int, limit: Int): Long = { k: Long -> if (k < 0) 0L else k * (k - 1) / 2 }.let { c -> c(n.toLong() + 2) - 3 * c(n.toLong() - limit + 1) + 3 * c(n.toLong() - 2 * limit) - c(n.toLong() - 3 * limit - 1) } }